    if (process.env.LOTUS_PANE_ID)
      read.caller_pane_id = process.env.LOTUS_PANE_ID;
    if (a.scope === "linked" || a.scope === "project")
      read.scope = a.scope;
    if (typeof a.projectId === "string" && a.projectId.trim())
      read.project_id = a.projectId.trim();
    if (Array.isArray(a.noteIds))
      read.note_ids = a.noteIds.filter((id) => typeof id === "string");
    if (typeof a.query === "string" && a.query.trim())
      read.query = a.query;
    if (Number.isFinite(a.limit))
      read.limit = Math.max(1, Math.trunc(a.limit));
    if (typeof a.includeContent === "boolean")
      read.include_content = a.includeContent;
    if (Number.isFinite(a.maxChars))
      read.max_chars = Math.max(1, Math.trunc(a.maxChars));
    const data = await callLotus("/v1/notes", { action: "read", read });
    return textResult(data);
